// agentDescription extracts the description from an Agent tool call.
func agentDescription(item views.ToolChainItem) string {
	if item.Params == nil {
		return ""
	}
	if item.Params.Description != "" {
		return item.Params.Description
	}
	// Codex spawn_agent uses agent_type
	if item.Params.AgentType != "" {
		return "Agent type: " + item.Params.AgentType
	}
	return ""
}

// agentPromptPreview extracts a preview of the agent prompt.
func agentPromptPreview(item views.ToolChainItem) string {
	if item.Params == nil {
		return ""
	}
	// Check both "prompt" (Claude Code) and "message" (Codex spawn_agent)
	p := item.Params.Prompt
	if p == "" {
		p = item.Params.Message
	}
	if p == "" {
		return ""
	}
	if len(p) > 500 {
		return p[:500] + "..."
	}
	return p
}

// agentID extracts the agent ID from the tool result output.
// The Agent tool result typically contains "agentId: <id>" in the output text.
// We check the full ResultEvent text since the output preview is often truncated.
func agentID(item views.ToolChainItem) string {
	const prefix = "agentId: "
	// Check full result text content first, then fall back to output preview
	var sources [3]string
	n := 0
	if item.ResultEvent != nil {
		sources[n] = item.ResultEvent.TextContent
		n++
		sources[n] = item.ResultEvent.TextPreview
		n++
	}
	sources[n] = toolOutputText(item)
	n++

	for _, output := range sources[:n] {
		idx := strings.Index(output, prefix)
		if idx < 0 {
			continue
		}
		after := output[idx+len(prefix):]
		end := strings.IndexAny(after, "\n )")
		if end < 0 {
			end = len(after)
		}
		if end > 0 {
			return after[:end]
		}
	}
	return ""
}

func toolDisplayName(name string) string {
	if name == "" {
		return "tool"
	}
	return name
}

func turnDividerText(ct views.ChatTurn) string {
	totalTools := 0
	for _, s := range ct.ToolStats {
		totalTools += s.Count
	}
	parts := fmt.Sprintf("Turn %d — %s tokens", ct.TurnSeq, views.FormatTokens(ct.TotalTokens))
	if totalTools > 0 {
		parts += fmt.Sprintf(" — %s", views.Pluralize(totalTools, "tool call"))
	}
	return parts
}

func chatDisplayText(e views.EventSummary) string {
	if e.TextContent != "" {
		return e.TextContent
	}
	return e.TextPreview
}

func chatCleanUserText(e views.EventSummary) string {
	return views.CleanSystemTags(chatDisplayText(e))
}

// toolOutputText returns the full tool output for display, preferring the
// complete output_json over the 320-char truncated OutputPreview.
// System tags are stripped so they don't leak into the rendered transcript.
func toolOutputText(item views.ToolChainItem) string {
	if item.OutputJSON != "" {
		return views.CleanSystemTags(item.OutputJSON)
	}
	return views.CleanSystemTags(item.OutputPreview)
}

// shouldTruncate decides whether content should start collapsed.
// Two checks: (i) content is non-trivial, (ii) enough would be hidden
// to justify a toggle. The 300px visible area fits roughly 1200 chars
// or 15 lines; we require content well beyond that to avoid truncating
// blocks that barely overflow.
func shouldTruncate(text string) bool {
	n := len(text)
	if n < 600 {
		return false
	}
	if n > 1800 {
		return true
	}
	lines := 0
	for i := 0; i < n; i++ {
		if text[i] == '\n' {
			lines++
			if lines >= 18 {
				return true
			}
		}
	}
	return false
}

func shouldTruncateMulti(events []views.EventSummary) bool {
	totalLen := 0
	totalLines := 0
	for _, e := range events {
		totalLen += len(e.TextContent)
		if totalLen > 1800 {
			return true
		}
		for i := 0; i < len(e.TextContent); i++ {
			if e.TextContent[i] == '\n' {
				totalLines++
				if totalLines >= 18 {
					return true
				}
			}
		}
	}
	if totalLen < 600 {
		return false
	}
	return false
}

// hasReasoningText returns true if at least one event has non-empty thinking text.
func hasReasoningText(events []views.EventSummary) bool {
	for _, e := range events {
		if e.TextContent != "" {
			return true
		}
	}
	return false
}

// hasEncryptedReasoning returns true if any event has encrypted reasoning content.
func hasEncryptedReasoning(events []views.EventSummary) bool {
	for _, e := range events {
		if e.PayloadType == "encrypted" {
			return true
		}
	}
	return false
}

